catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        return;
    }

    // Pega o sys_id do treinamento selecionado
    var trainingNameSysId = g_form.getValue('choose_the_training_that_you_want_to_enroll_in');
    console.log("Rodou e temos o training: " + trainingNameSysId);

	// Pega o sys_id do usuário atual
    var userId = g_user.userID;
	console.log("UserId: " + userId);


    // Limpa o campo training_schedules
    g_form.clearOptions('training_schedules_dates');
    console.log("Limpou as opcoes");

    // Busca as datas disponíveis para o treinamento selecionado
    var gaToShowDates = new GlideAjax('AooPemyUtilsAjax'); // Nome do Script Include
    gaToShowDates.addParam('sysparm_name', 'getAvailableDates');
    gaToShowDates.addParam('sysparm_training_name', trainingNameSysId);
    console.log("Passou os parametros do GlideAjax");

    gaToShowDates.getXMLAnswer(function(response) {
		var dates = JSON.parse(response); // Converte a resposta em um array de datas
		console.log(dates);
		if (dates.length > 0) {
			// Verifica se o usuário já se matriculou 3 vezes no curso
			console.log("Entrando no segundo GlideAjax");
			var gaCount = new GlideAjax('AooPemyUtilsAjax');
			gaCount.addParam('sysparm_name', 'getRegistrationCount');
			gaCount.addParam('sysparm_training_name', trainingNameSysId);
			gaCount.addParam('sysparm_user', userId);

			gaCount.getXMLAnswer(function(countResponse) {
				var count = parseInt(countResponse);
				console.log("Count: " + count);
				if (count >= 3) {
					alert('Você já se matriculou 3 vezes neste curso. Não é possível se matricular novamente.');
					g_form.clearOptions('training_schedules');
				} else {

					new Promise(function(resolve, reject) {
                    try {
                        dates.forEach(function(date) {
                            console.log("Valor da data ao final da validação: " + date);
                            g_form.addOption('training_schedules_dates', date, date); // Adiciona as opções ao Select Box
                        });
                        resolve(); // Resolve a Promise após adicionar todas as opções
                    } catch (error) {
                        reject(error); // Rejeita a Promise em caso de erro
                    }
                });

				var trainingDate = g_form.getValue('training_schedules_dates');
				console.log("Valor data função onChange:" + trainingDate);

				getSysIdToSubmitRecord(trainingNameSysId, trainingDate)
				.then(function(setSchdulerSysId){

				console.log("Valor do JSON " + setSchdulerSysId);
				var jsonToString = JSON.parse(setSchdulerSysId);
				console.log("Valor do array: " + jsonToString);
				console.log("Valor do array 0 String: " + jsonToString[0]);
				console.log("Valor do array 1 String: " + jsonToString[1]);
				if(parseInt(jsonToString[1]) === 0) {
					alert('As vagas para esse treinamento e/ou data já foram esgotadas.'); 
				}else{
					console.log("Usuário não está matriculado. Prosseguindo com a inscrição.");
					console.log("(Submit) - SysId " + jsonToString[0]);
					g_form.setValue('training_schedules_set', jsonToString[0]);
				}
				});

				}
			});

		} else {
			g_form.addOption('training_schedules', '', 'Nenhuma data disponível'); // Mensagem se não houver datas
		}




    });

}
    //Type appropriate comment here, and begin script below

	function getSysIdToSubmitRecord(trainingNameSysId, trainingDate) {
    return new Promise(function(resolve, reject) {
        var gaScheduler = new GlideAjax('AooPemyUtilsAjax');
        gaScheduler.addParam('sysparm_name', 'getSchedulerSysId');
        gaScheduler.addParam('sysparm_training_date', trainingDate);
        gaScheduler.addParam('sysparm_training_name', trainingNameSysId);

        gaScheduler.getXMLAnswer(function(registrationResponse) {
            console.log("(Submit) Response: " + registrationResponse);
            var arrayResponse = registrationResponse.split(',');
            resolve(arrayResponse); // Resolve a Promise com a resposta
        });
    });

}
